# The stock ledger of PLAN §2.3 (flag INVENTORY_STOCK). Generated by Django 6.0.8, then extended by hand with:
# * the inventory_balance VIEW (signed sum of the movements per component and location; Balance maps it unmanaged,
#   its relations are written into the state by hand because the autodetector leaves them out of unmanaged models);
# * the append-only privileges of inventory_movement (REVOKE UPDATE, DELETE, TRUNCATE from DB_APP_ROLE, as audit_log).

import django.db.models.deletion
import django.db.models.functions.text
import django.utils.timezone
