from django.conf import settings
from django.db import migrations, models

BALANCE_VIEW_SQL = """
CREATE VIEW inventory_balance AS
SELECT m.component_id,
       m.location_id,
       CAST(SUM(CASE WHEN m.direction = 'IN' THEN m.qty ELSE -m.qty END) AS numeric(18, 3)) AS qty,
       CAST(SUM(CASE WHEN m.direction = 'IN' THEN m.qty ELSE 0 END) AS numeric(18, 3)) AS qty_in,
       CAST(SUM(CASE WHEN m.direction = 'OUT' THEN m.qty ELSE 0 END) AS numeric(18, 3)) AS qty_out,
       CAST(COUNT(*) AS integer) AS movement_count,
       MAX(m.at) AS last_movement_at
FROM inventory_movement m
WHERE m.deleted_at IS NULL
GROUP BY m.component_id, m.location_id;
"""


def apply_append_only(apps, schema_editor):
    """REVOKE UPDATE, DELETE, TRUNCATE on inventory_movement from DB_APP_ROLE when the app runs as another role."""
    role = (getattr(settings, "DB_APP_ROLE", "") or "").strip()
    if not role:
        return
    with schema_editor.connection.cursor() as cursor:
        cursor.execute("SELECT current_user")
        if cursor.fetchone()[0] == role:
            return
    from inventory.services.privileges import apply_append_only_privileges

    apply_append_only_privileges(role)


